Here is the commit message:
fs/omfs: reject s_sys_blocksize smaller than OMFS_DIR_START

omfs_fill_super() rejects oversized s_sys_blocksize values (> PAGE_SIZE),
but it does not reject values smaller than OMFS_DIR_START (0x1b8 = 440).

Later, omfs_make_empty() uses

    sbi->s_sys_blocksize - OMFS_DIR_START

as the length argument to memset().  Since s_sys_blocksize is u32,
a crafted filesystem image with s_sys_blocksize < OMFS_DIR_START causes
an unsigned underflow there, wrapping to a value near 2^32.  That drives
a ~4 GiB memset() from bh->b_data + OMFS_DIR_START and overwrites kernel
memory far beyond the backing block buffer.

Add the corresponding lower-bound check alongside the existing upper-bound
check in omfs_fill_super(), so that malformed images are rejected during
superblock validation before any filesystem data is processed.

Fixes: a3ab7155ea21 ("omfs: add directory routines")
Signed-off-by: Hyungjung Joo <jhj140711@gmail.com>
Link: https://patch.msgid.link/20260317054827.1822061-1-jhj140711@gmail.com
Signed-off-by: Christian Brauner <brauner@kernel.org>

Here is the root cause:
The omfs_fill_super() function in fs/omfs/inode.c does not validate that s_sys_blocksize is at least OMFS_DIR_START before it is used in omfs_make_empty(). A crafted filesystem with s_sys_blocksize smaller than OMFS_DIR_START causes an unsigned integer underflow in the memset() length calculation (sbi->s_sys_blocksize - OMFS_DIR_START), resulting in a massive memory overwrite.

Here is the patch:

 static int omfs_fill_super(struct super_block *sb, struct fs_context *fc)
 {
 	struct buffer_head *bh, *bh2;
 	struct omfs_super_block *omfs_sb;
 	struct omfs_root_block *omfs_rb;
 	struct omfs_sb_info *sbi;
 	struct inode *root;
 	struct omfs_mount_options *parsed_opts = fc->fs_private;
 	int ret = -EINVAL;
 	int silent = fc->sb_flags & SB_SILENT;

 	sbi = kzalloc(sizeof(struct omfs_sb_info), GFP_KERNEL);
 	if (!sbi)
 		return -ENOMEM;

 	sb->s_fs_info = sbi;

 	omfs_set_options(sbi, parsed_opts);

 	sb->s_maxbytes = 0xffffffff;

 	sb->s_time_gran = NSEC_PER_MSEC;
 	sb->s_time_min = 0;
 	sb->s_time_max = U64_MAX / MSEC_PER_SEC;

 	sb_set_blocksize(sb, 0x200);

 	bh = sb_bread(sb, 0);
 	if (!bh)
 		goto end;

 	omfs_sb = (struct omfs_super_block *)bh->b_data;

 	if (omfs_sb->s_magic != cpu_to_be32(OMFS_MAGIC)) {
 		if (!silent)
 			printk(KERN_ERR "omfs: Invalid superblock (%x)\n",
 				   omfs_sb->s_magic);
 		goto out_brelse_bh;
 	}
 	sb->s_magic = OMFS_MAGIC;

 	sbi->s_num_blocks = be64_to_cpu(omfs_sb->s_num_blocks);
 	sbi->s_blocksize = be32_to_cpu(omfs_sb->s_blocksize);
 	sbi->s_mirrors = be32_to_cpu(omfs_sb->s_mirrors);
 	sbi->s_root_ino = be64_to_cpu(omfs_sb->s_root_block);
 	sbi->s_sys_blocksize = be32_to_cpu(omfs_sb->s_sys_blocksize);
 	mutex_init(&sbi->s_bitmap_lock);

 	if (sbi->s_num_blocks > OMFS_MAX_BLOCKS) {
 		printk(KERN_ERR "omfs: sysblock number (%llx) is out of range\n",
 		       (unsigned long long)sbi->s_num_blocks);
 		goto out_brelse_bh;
 	}

 	if (sbi->s_sys_blocksize > PAGE_SIZE) {
 		printk(KERN_ERR "omfs: sysblock size (%d) is out of range\n",
 			sbi->s_sys_blocksize);
 		goto out_brelse_bh;
 	}

+	if (sbi->s_sys_blocksize < OMFS_DIR_START) {
+		printk(KERN_ERR "omfs: sysblock size (%d) is too small\n",
+			sbi->s_sys_blocksize);
+		goto out_brelse_bh;
+	}
+
 	if (sbi->s_blocksize < sbi->s_sys_blocksize ||
 	    sbi->s_blocksize > OMFS_MAX_BLOCK_SIZE) {
 		printk(KERN_ERR "omfs: block size (%d) is out of range\n",
 			sbi->s_blocksize);
 		goto out_brelse_bh;
 	}

 	/*
 	 * Use sys_blocksize as the fs block since it is smaller than a
 	 * page while the fs blocksize can be larger.
 	 */
 	sb_set_blocksize(sb, sbi->s_sys_blocksize);

 	/*
 	 * ...and the difference goes into a shift.  sys_blocksize is always
 	 * a power of two factor of blocksize.
 	 */
 	sbi->s_block_shift = get_bitmask_order(sbi->s_blocksize) -
 		get_bitmask_order(sbi->s_sys_blocksize);

 	bh2 = omfs_bread(sb, be64_to_cpu(omfs_sb->s_root_block));
 	if (!bh2)
 		goto out_brelse_bh;

 	omfs_rb = (struct omfs_root_block *)bh2->b_data;

 	sbi->s_bitmap_ino = be64_to_cpu(omfs_rb->r_bitmap);
 	sbi->s_clustersize = be32_to_cpu(omfs_rb->r_clustersize);

 	if (sbi->s_num_blocks != be64_to_cpu(omfs_rb->r_num_blocks)) {
 		printk(KERN_ERR "omfs: block count discrepancy between "
 			"super and root blocks (%llx, %llx)\n",
 			(unsigned long long)sbi->s_num_blocks,
 			(unsigned long long)be64_to_cpu(omfs_rb->r_num_blocks));
 		goto out_brelse_bh2;
 	}

 	if (sbi->s_bitmap_ino != ~0ULL &&
 	    sbi->s_bitmap_ino > sbi->s_num_blocks) {
 		printk(KERN_ERR "omfs: free space bitmap location is corrupt "
 			"(%llx, total blocks %llx)\n",
 			(unsigned long long) sbi->s_bitmap_ino,
 			(unsigned long long) sbi->s_num_blocks);
 		goto out_brelse_bh2;
 	}
 	if (sbi->s_clustersize < 1 ||
 	    sbi->s_clustersize > OMFS_MAX_CLUSTER_SIZE) {
 		printk(KERN_ERR "omfs: cluster size out of range (%d)",
 			sbi->s_clustersize);
 		goto out_brelse_bh2;
 	}

 	ret = omfs_get_imap(sb);
 	if (ret)
 		goto out_brelse_bh2;

 	sb->s_op = &omfs_sops;

 	root = omfs_iget(sb, be64_to_cpu(omfs_rb->r_root_dir));
 	if (IS_ERR(root)) {
 		ret = PTR_ERR(root);
 		goto out_brelse_bh2;
 	}

 	sb->s_root = d_make_root(root);
 	if (!sb->s_root) {
 		ret = -ENOMEM;
 		goto out_brelse_bh2;
 	}
 	printk(KERN_DEBUG "omfs: Mounted volume %s\n", omfs_rb->r_name);

 	ret = 0;
 out_brelse_bh2:
 	brelse(bh2);
 out_brelse_bh:
 	brelse(bh);
 end:
 	if (ret)
 		kfree(sbi);
 	return ret;
 }



